/* unorm -- Unicode normalisation form KC (NFKC) of UTF-8 text, as
 * JavaScript's String.prototype.normalize("NFKC") gives it: amiga-pi's edit
 * matches the way pi does (pi f10993bc tools/edit-diff.ts
 * normalizeForFuzzyMatch). Unicode 16.0 (claude/unorm_tab.h, generated by
 * tools/gen_unorm.py). Full compatibility decomposition, canonical ordering,
 * canonical composition (Hangul algorithmic).
 * Portable C89, host-tested against Python's unicodedata (tests/test_unorm.py). */
#ifndef CL_UNORM_H
#define CL_UNORM_H

/* NFKC of s[0..n) (UTF-8; a byte that is not UTF-8 counts as U+FFFD, as a
 * JavaScript decoder makes it): a malloc'ed, terminated UTF-8 text in *out,
 * its length in *on. 0, -1 out of memory. */
int un_nfkc(const char *s, long n, char **out, long *on);
/* the canonical combining class of a code point (0 for a starter) */
int un_ccc(unsigned long c);

#endif
